import csv, sys
d = sys.argv[1]
t = {r['region']: r for r in csv.DictReader(open(d + '/this_week.csv'))}
l = {r['region']: r for r in csv.DictReader(open(d + '/last_week.csv'))}
for m in ['orders', 'revenue_gbp', 'active_customers']:
    a = sum(int(t[k][m]) for k in t)
    b = sum(int(l[k][m]) for k in l)
    print(m, b, a, a - b, round((a - b) / b * 100, 2))
    for k in t:
        x = int(t[k][m]); y = int(l[k][m])
        print('  ', k, y, x, x - y, round((x - y) / y * 100, 2))
for k in t:
    for w, dd in (('L', l), ('T', t)):
        print(k, w, 'AOV', round(int(dd[k]['revenue_gbp']) / int(dd[k]['orders']), 2))
for w, dd in (('L', l), ('T', t)):
    print(w, 'AOV', round(sum(int(dd[k]['revenue_gbp']) for k in dd) / sum(int(dd[k]['orders']) for k in dd), 2))

